<template>
<div class="service-desk">
 <aside class="conversation-list"><div class="desk-list-heading"><h3>客户会话</h3><el-button text @click="refresh" :loading="loading"><el-icon><Refresh/></el-icon></el-button></div><el-input v-model="keyword" placeholder="搜索客户或消息" clearable/><el-radio-group v-model="filter" size="small" class="conversation-filters"><el-radio-button label="all">全部</el-radio-button><el-radio-button label="waiting">待接待</el-radio-button><el-radio-button label="human">人工中</el-radio-button></el-radio-group><div class="conversation-scroll"><button v-for="item in filtered" :key="item.userid" class="conversation-item" :class="{selected:active?.userid===item.userid}" @click="select(item)"><div><strong>{{item.name}}</strong><el-tag size="small" :type="item.mode==='waiting'?'warning':item.mode==='human'?'success':'info'">{{labels[item.mode]}}</el-tag></div><p>{{item.preview}}</p><small>{{item.addtime}} <b v-if="item.pending">待回复</b></small></button><el-empty v-if="!filtered.length" description="暂无会话"/></div></aside>
 <section class="conversation-main" v-if="active"><header><div><strong>{{active.name}}</strong><span>{{labels[active.mode]}} · 聊天记录自动更新</span></div><div><el-button v-if="active.mode!=='human'" type="primary" @click="action('accept')">接入人工</el-button><el-button v-else @click="action('close')">结束接待</el-button></div></header><div ref="history" class="desk-history"><article v-for="m in messages" :key="m.id" :class="{outgoing:!m.ask}"><small>{{m.ask?active.name:Number(m.adminid)===0?'智能助手 / 系统':'人工客服'}} · {{m.addtime}}</small><div class="desk-bubble"><el-image v-if="isImage(m.ask||m.reply)" :src="media(m.ask||m.reply)" :preview-src-list="[media(m.ask||m.reply)]"/><video v-else-if="isVideo(m.ask||m.reply)" :src="media(m.ask||m.reply)" controls/><span v-else>{{m.ask||m.reply}}</span></div></article></div><footer><div class="quick-replies"><el-button v-for="text in quick" :key="text" size="small" @click="draft=text">{{text}}</el-button></div><el-input v-model="draft" type="textarea" :rows="3" maxlength="2000" show-word-limit placeholder="输入回复，Enter 发送，Shift + Enter 换行；发送后自动接入人工" @keydown="onMessageKeydown"/><div class="desk-send"><span>回复将直接同步到客户的咨询窗口</span><el-button type="primary" :loading="sending" :disabled="!draft.trim()" @click="send">发送回复</el-button></div></footer></section><el-empty v-else class="conversation-main" description="选择左侧客户开始接待"/>
</div>
</template>
<script setup>
import {ref,computed,getCurrentInstance,onMounted,onBeforeUnmount,nextTick} from 'vue'
const ctx=getCurrentInstance().appContext.config.globalProperties
const conversations=ref([]),active=ref(null),messages=ref([]),draft=ref(''),keyword=ref(''),filter=ref('all'),loading=ref(false),sending=ref(false),history=ref()
const labels={bot:'智能接待',waiting:'等待人工',human:'人工接待'}
const quick=['您好，请问有什么可以帮您？','请提供预约编号，我帮您核实。','感谢您的咨询，祝您生活愉快！']
const filtered=computed(()=>conversations.value.filter(i=>(filter.value==='all'||i.mode===filter.value)&&((i.name||'')+(i.preview||'')).includes(keyword.value)))
const media=v=>ctx.$config.url+v,isImage=v=>/^file\/[^\s]+\.(png|jpe?g|gif|webp)$/i.test(v||''),isVideo=v=>/^file\/[^\s]+\.mp4$/i.test(v||'')
let timer,disposed=false,seq=0
async function loadMessages(){if(!active.value)return;const id=active.value.userid,n=++seq;const near=!history.value||history.value.scrollHeight-history.value.scrollTop-history.value.clientHeight<80;const res=await ctx.$http.get('chat/page',{params:{userid:id,page:1,limit:200,sort:'id',order:'desc'}});if(disposed||n!==seq||id!==active.value?.userid)return;messages.value=res.data.data.list.reverse();await nextTick();if(near&&history.value)history.value.scrollTop=history.value.scrollHeight}
async function refresh(){if(loading.value)return;loading.value=true;try{const res=await ctx.$http.get('chat/conversations');if(disposed)return;conversations.value=res.data.data;if(active.value){active.value=conversations.value.find(i=>i.userid===active.value.userid)||null}await loadMessages()}catch{ctx.$toolUtil.message('会话加载失败，请刷新重试','error')}finally{loading.value=false}}
async function select(item){if(draft.value.trim()&&active.value?.userid!==item.userid){ctx.$toolUtil.message('请先发送或清空当前草稿，再切换客户','warning');return}active.value=item;messages.value=[];await loadMessages()}
async function action(type){try{await ctx.$http.post('chat/session/'+active.value.userid+'/'+type);await refresh()}catch{ctx.$toolUtil.message('操作失败，请重试','error')}}
function onMessageKeydown(event){
 if(event.key!=='Enter'||event.shiftKey||event.isComposing||event.keyCode===229)return
 event.preventDefault()
 if(event.repeat)return
 send()
}
async function send(){const text=draft.value.trim(),id=active.value?.userid;if(!text||!id||sending.value)return;sending.value=true;try{await ctx.$http.post('chat/save',{userid:id,reply:text});draft.value='';await refresh();await nextTick();if(history.value)history.value.scrollTop=history.value.scrollHeight}catch{ctx.$toolUtil.message('发送失败，草稿已保留','error')}finally{sending.value=false}}
async function poll(){await refresh();if(!disposed)timer=setTimeout(poll,4000)}
onMounted(poll);onBeforeUnmount(()=>{disposed=true;seq++;clearTimeout(timer)})
</script>
<style scoped>
.service-desk{display:flex;background:var(--desk-surface,#fff);border:1px solid var(--el-border-color-light);border-radius:10px;height:calc(100vh - 210px);min-height:580px;overflow:hidden}.conversation-list{width:310px;flex-shrink:0;border-right:1px solid var(--el-border-color-light);padding:18px;display:flex;flex-direction:column;gap:14px}.desk-list-heading{display:flex;align-items:center;justify-content:space-between}.desk-list-heading h3{margin:0;font-size:16px}.conversation-scroll{overflow:auto;flex:1}.conversation-item{display:block;width:100%;background:transparent;border:0;border-radius:8px;text-align:left;padding:14px 10px;cursor:pointer;color:var(--el-text-color-primary)}.conversation-item.selected{background:var(--el-color-primary-light-9)}.conversation-item>div{display:flex;justify-content:space-between;gap:8px}.conversation-item p{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:13px;color:var(--el-text-color-regular)}.conversation-item small{font-size:11px;color:var(--el-text-color-secondary)}.conversation-item b{color:var(--el-color-warning);margin-left:8px}.conversation-main{flex:1;min-width:0;display:flex;flex-direction:column}.conversation-main>header{padding:20px 24px;border-bottom:1px solid var(--el-border-color-light);display:flex;justify-content:space-between;align-items:center}.conversation-main header span{display:block;color:var(--el-text-color-secondary);font-size:12px;margin-top:6px}.desk-history{flex:1;overflow:auto;background:var(--desk-canvas,#f5f7fa);padding:24px}.desk-history article{display:flex;flex-direction:column;align-items:flex-start;margin-bottom:22px}.desk-history article.outgoing{align-items:flex-end}.desk-history small{font-size:11px;color:var(--el-text-color-secondary);margin-bottom:7px}.desk-bubble{background:var(--desk-surface,#fff);padding:12px 16px;border-radius:0 10px 10px;max-width:85%;font-size:14px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;border:1px solid var(--el-border-color-lighter)}.outgoing .desk-bubble{background:var(--el-color-primary-light-9);border-radius:10px 0 10px 10px}.desk-bubble .el-image,.desk-bubble video{max-width:240px;max-height:180px}.conversation-main>footer{padding:16px 24px}.quick-replies{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}.quick-replies .el-button{margin:0}.desk-send{display:flex;justify-content:space-between;align-items:center;margin-top:12px}.desk-send span{font-size:12px;color:var(--el-text-color-secondary)}@media(max-width:1000px){.conversation-list{width:230px;padding:12px}.conversation-main>footer{padding:12px}.desk-send span{display:none}}@media(max-width:650px){.service-desk{flex-direction:column;height:auto}.conversation-list{width:100%;height:260px;border-right:0}.conversation-main{min-height:560px}.desk-history{max-height:400px}.conversation-main>header{padding:16px}}
</style>
